fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // We only need to check parent indices from 0 to (n/2) - 1
    for i in 0..(n / 2) {
        let parent = a[i];
        
        // Check left child
        let left_index = 2 * i + 1;
        if left_index < n {
            if a[left_index] < parent {
                return false; // Left child is less than parent
            }
        }
        
        // Check right child
        let right_index = 2 * i + 2;
        if right_index < n {
            if a[right_index] < parent {
                return false; // Right child is less than parent
            }
        }
    }
    
    true // All parent-child comparisons satisfied the min-heap property
}